import { Buffer } from 'node:buffer';
import { randomBytes, randomUUID, scrypt, createHash, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';
import PDFDocument from 'npm:pdfkit@0.20.2';
import ExcelJS from 'npm:exceljs@4.4.0';
import postgres from 'npm:postgres@3.4.7';
const currencies = {
  INR: 2,
  USD: 2,
  EUR: 2,
  GBP: 2,
  VND: 0,
  JPY: 0,
  THB: 2,
  AUD: 2,
  CAD: 2,
  SGD: 2,
  AED: 2,
};
function assert(ok, message, status = 400) {
  if (!ok) throw Object.assign(new Error(message), { status });
}
function minor(value, currency) {
  assert(Object.hasOwn(currencies, currency), 'Unsupported currency');
  const decimals = currencies[currency];
  const s = String(value ?? '').trim();
  assert(
    new RegExp(decimals ? `^\\d{1,10}(?:\\.\\d{1,${decimals}})?$` : '^\\d{1,10}$').test(s),
    `Enter a valid ${currency} amount (${decimals} decimal places)`,
  );
  const n = Math.round(Number(s) * 10 ** decimals);
  assert(
    Number.isSafeInteger(n) && n > 0 && n <= 1e12,
    'Amount must be greater than zero and within the limit',
  );
  return n;
}
function allocate(total, weights) {
  assert(Number.isSafeInteger(total) && total >= 0, 'Invalid allocation total');
  assert(
    weights.length > 0 && weights.every((w) => Number.isFinite(w) && w >= 0),
    'Invalid split values',
  );
  const sum = weights.reduce((a, b) => a + b, 0);
  assert(sum > 0 && Number.isFinite(sum), 'Choose at least one participant');
  const parts = weights.map((w, i) => ({ i, raw: total * (w / sum) }));
  const result = parts.map((p) => Math.floor(p.raw));
  let left = total - result.reduce((a, b) => a + b, 0);
  parts.sort((a, b) => b.raw - Math.floor(b.raw) - (a.raw - Math.floor(a.raw)) || a.i - b.i);
  for (let i = 0; i < left; i++) result[parts[i % parts.length].i]++;
  return result;
}
function participants(rows, trip) {
  assert(Array.isArray(rows) && rows.length > 0 && rows.length <= 100, 'Choose participants');
  assert(
    new Set(rows.map((r) => r.memberId)).size === rows.length,
    'Each member can appear only once',
  );
  assert(
    rows.every((r) => trip.members.some((m) => m.id === r.memberId)),
    'A selected member is not in this group',
  );
}
function expenseFromInput(input, trip) {
  const currency = input.currency || trip.currency;
  const amount = minor(input.amount, currency);
  const rate = currency === trip.currency ? 1 : Number(input.rate);
  assert(
    Number.isFinite(rate) && rate >= 0.000001 && rate <= 1e6,
    'Enter an exchange rate to the group currency',
  );
  const total = Math.round(
    (amount / 10 ** currencies[currency]) * rate * 10 ** currencies[trip.currency],
  );
  assert(
    Number.isSafeInteger(total) && total > 0 && total <= 1e12,
    'Converted amount is outside the limit',
  );
  const shares = input.shares;
  const payers = input.payers;
  participants(shares, trip);
  participants(payers, trip);
  const mode = input.mode || 'equal';
  assert(['equal', 'exact', 'percent', 'shares'].includes(mode), 'Invalid split method');
  let weights;
  if (mode === 'equal') weights = shares.map(() => 1);
  else if (mode === 'exact') {
    weights = shares.map((s) => (Number(s.value) === 0 ? 0 : minor(s.value, currency)));
    assert(
      weights.reduce((a, b) => a + b, 0) === amount,
      'Exact shares must add up to the expense amount',
    );
  } else {
    weights = shares.map((s) => Number(s.value));
    assert(
      weights.every((w) => Number.isFinite(w) && w >= 0 && w <= 1e9),
      'Enter valid split values',
    );
    if (mode === 'percent')
      assert(
        Math.abs(weights.reduce((a, b) => a + b, 0) - 100) < 0.000001,
        'Percentages must add up to 100',
      );
  }
  const paid =
    payers.length === 1
      ? [amount]
      : payers.map((p) => (Number(p.amount) === 0 ? 0 : minor(p.amount, currency)));
  assert(paid.reduce((a, b) => a + b, 0) === amount, 'Payments must add up to the expense amount');
  const splitAmounts = allocate(total, weights);
  const paidAmounts = allocate(total, paid);
  return {
    currency,
    originalAmount: amount,
    rate,
    amount: total,
    mode,
    shares: shares.map((s, i) => ({
      memberId: s.memberId,
      value: s.value ?? '',
      amount: splitAmounts[i],
    })),
    payers: payers.map((p, i) => ({
      memberId: p.memberId,
      amount: paidAmounts[i],
      originalAmount: paid[i],
    })),
  };
}
function balances(trip) {
  const rows = Object.fromEntries(
    trip.members.map((m) => [m.id, { ...m, paid: 0, spent: 0, balance: 0 }]),
  );
  for (const e of trip.expenses) {
    for (const p of e.payers) {
      rows[p.memberId].paid += p.amount;
      rows[p.memberId].balance += p.amount;
    }
    for (const s of e.shares) {
      rows[s.memberId].spent += s.amount;
      rows[s.memberId].balance -= s.amount;
    }
  }
  for (const t of trip.transfers) {
    rows[t.from].balance += t.amount;
    rows[t.to].balance -= t.amount;
  }
  return Object.values(rows);
}
function settlements(trip) {
  const rows = balances(trip);
  const debtors = rows
    .filter((r) => r.balance < 0)
    .map((r) => ({ id: r.id, n: -r.balance }))
    .sort((a, b) => b.n - a.n);
  const creditors = rows
    .filter((r) => r.balance > 0)
    .map((r) => ({ id: r.id, n: r.balance }))
    .sort((a, b) => b.n - a.n);
  const out = [];
  let i = 0,
    j = 0;
  while (i < debtors.length && j < creditors.length) {
    const amount = Math.min(debtors[i].n, creditors[j].n);
    out.push({ from: debtors[i].id, to: creditors[j].id, amount });
    debtors[i].n -= amount;
    creditors[j].n -= amount;
    if (!debtors[i].n) i++;
    if (!creditors[j].n) j++;
  }
  return out;
}

const amount = (n, c) => `${c} ${(n / 10 ** currencies[c]).toFixed(currencies[c])}`;
function auditSnapshot(trip) {
  const result = {};
  const put = (key, label, value) => {
    result[key] = { label, value: String(value ?? '') };
  };
  const name = (id) => trip.members.find((m) => m.id === id)?.name || 'Former member';
  put('name', 'Group name', trip.name);
  put('currency', 'Currency', trip.currency);
  put('categories', 'Group categories', (trip.categories || []).join(', '));
  for (const m of trip.members)
    put(`member:${m.id}`, 'Member', `${m.name}${m.userId ? ' (joined)' : ' (guest)'}`);
  for (const e of trip.expenses) {
    const fields = {
      Title: e.title,
      Amount: amount(e.amount, trip.currency),
      Category: e.category,
      Date: e.date,
      'Original amount': amount(e.originalAmount, e.currency),
      'Exchange rate': e.rate,
      'Split method': e.mode,
      Note: e.note,
      Attachments: (e.attachments || []).map(file => file.name).join(', '),
      'Paid by': e.payers
        .map((p) => `${name(p.memberId)}: ${amount(p.amount, trip.currency)}`)
        .join(', '),
      Shares: e.shares
        .map((s) => `${name(s.memberId)}: ${amount(s.amount, trip.currency)}`)
        .join(', '),
    };
    for (const [field, value] of Object.entries(fields))
      put(`bill:${e.id}:${field}`, `Bill “${e.title}” · ${field}`, value);
  }
  for (const t of trip.transfers) {
    for (const [field, value] of Object.entries({
      From: name(t.from),
      To: name(t.to),
      Amount: amount(t.amount, trip.currency),
      Date: t.date,
      Note: t.note,
    }))
      put(`transfer:${t.id}:${field}`, `Transfer · ${field}`, value);
  }
  return result;
}
function auditChanges(before, after) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])]
    .filter((key) => before[key]?.value !== after[key]?.value)
    .map((key) => ({
      field: (after[key] || before[key]).label,
      before: before[key]?.value || '',
      after: after[key]?.value || '',
    }));
}

const regular = Buffer.from('', 'base64');
const bold = Buffer.from('', 'base64');
const value = (n, c) => n / 10 ** currencies[c];
const money = (n, c) =>
  `${c} ${value(n, c).toLocaleString('en-IN', { minimumFractionDigits: currencies[c], maximumFractionDigits: currencies[c] })}`;
const ledgerDate = entry => entry.createdAt ? `${entry.date}\nLogged ${new Date(entry.createdAt).toISOString().slice(0,16).replace('T',' ')} UTC` : entry.date;
async function exportTrip(trip, format, { analytics = false } = {}) {
  const name = (id) => trip.members.find((m) => m.id === id)?.name || 'Former member';
  if (format === 'xlsx') {
    const book = new ExcelJS.Workbook();
    book.creator = 'SplitBill';
    book.created = new Date();
    const sheet = (title, headers, rows, widths, numbers = []) => {
      const ws = book.addWorksheet(title, { views: [{ state: 'frozen', ySplit: 1 }] });
      ws.addRow(headers);
      ws.addRows(rows);
      ws.columns.forEach((column, i) => {
        column.width = widths[i] || 24;
      });
      ws.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } };
      ws.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF193E30' } };
      ws.getRow(1).height = 28;
      ws.eachRow((row, index) => {
        row.alignment = { vertical: 'top', wrapText: true };
        if (index > 1) {
          row.height = ['Activity','Expenses','Transfers'].includes(title) ? 54 : 34;
          row.font = { name: 'Calibri', size: 11 };
        }
      });
      for (const col of numbers)
        ws.getColumn(col).numFmt =
          `"${trip.currency}" #,##0.${'0'.repeat(currencies[trip.currency])};[Red]-"${trip.currency}" #,##0.${'0'.repeat(currencies[trip.currency])}`
            .replaceAll('0.;', '0;')
            .replace(/0\.$/, '0');
      ws.autoFilter = {
        from: { row: 1, column: 1 },
        to: { row: Math.max(1, ws.rowCount), column: headers.length },
      };
      return ws;
    };
    sheet(
      'Summary',
      ['Group', 'Currency', 'Expense total', 'Bills', 'Transfers', 'Exported at'],
      [
        [
          trip.name,
          trip.currency,
          value(trip.total, trip.currency),
          trip.expenses.length,
          trip.transfers.length,
          new Date().toISOString(),
        ],
      ],
      [32, 14, 23, 12, 12, 29],
      [3],
    );
    sheet(
      'Balances',
      ['Member', 'Paid for bills', 'Share of bills', 'Net balance'],
      trip.balances.map((b) => [
        b.name,
        value(b.paid, trip.currency),
        value(b.spent, trip.currency),
        value(b.balance, trip.currency),
      ]),
      [30, 23, 23, 23],
      [2, 3, 4],
    );
    sheet(
      'Expenses',
      ['ID', 'Bill date / logged UTC', 'Description', 'Category', 'Paid by', 'Amount', 'Split method', 'Note'],
      trip.expenses.map((e) => [
        e.id,
        ledgerDate(e),
        e.title,
        e.category,
        e.payers.map((p) => name(p.memberId)).join(', '),
        value(e.amount, trip.currency),
        e.mode,
        e.note,
      ]),
      [38, 28, 38, 22, 32, 23, 18, 40],
      [6],
    );
    sheet(
      'Shares',
      ['Expense ID', 'Description', 'Member', 'Share'],
      trip.expenses.flatMap((e) =>
        e.shares.map((s) => [e.id, e.title, name(s.memberId), value(s.amount, trip.currency)]),
      ),
      [38, 38, 30, 23],
      [4],
    );
    sheet(
      'Payers',
      ['Expense ID', 'Description', 'Member', 'Paid'],
      trip.expenses.flatMap((e) =>
        e.payers.map((p) => [e.id, e.title, name(p.memberId), value(p.amount, trip.currency)]),
      ),
      [38, 38, 30, 23],
      [4],
    );
    sheet(
      'Transfers',
      ['Transfer date / logged UTC', 'From', 'To', 'Amount', 'Note'],
      trip.transfers.map((t) => [
        ledgerDate(t),
        name(t.from),
        name(t.to),
        value(t.amount, trip.currency),
        t.note,
      ]),
      [28, 30, 30, 23, 45],
      [4],
    );
    sheet(
      'Activity',
      ['Time', 'Who', 'Action', 'Field', 'Before', 'After'],
      (trip.activity || []).flatMap((a) =>
        (a.changes?.length ? a.changes : [{ field: '', before: '', after: '' }]).map((c) => [
          a.at,
          a.user,
          a.message,
          c.field,
          c.before,
          c.after,
        ]),
      ),
      [28, 25, 45, 45, 60, 60],
    );
    return Buffer.from(await book.xlsx.writeBuffer());
  }
  const doc = new PDFDocument({
    size: 'A4',
    margin: 42,
    bufferPages: true,
    info: { Title: `${trip.name} - SplitBill report`, Author: 'SplitBill' },
  });
  doc.registerFont('Regular', regular);
  doc.registerFont('Bold', bold);
  doc.font('Regular');
  const chunks = [];
  doc.on('data', (chunk) => chunks.push(chunk));
  const complete = new Promise((resolve, reject) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
  });
  const maxY = 785;
  const ensure = (height) => {
    if (doc.y + height > maxY) doc.addPage();
  };
  const paragraph = (text, { size = 10, color = '#233C30', strong = false } = {}) => {
    doc
      .font(strong ? 'Bold' : 'Regular')
      .fontSize(size)
      .fillColor(color);
    doc.text(String(text), 42, doc.y, { width: 511, paragraphGap: 5 });
  };
  const heading = (title) => {
    ensure(60);
    doc.moveDown(0.8);
    paragraph(title, { size: 16, strong: true, color: '#285443' });
    doc.moveDown(0.3);
  };
  const table = (headers, rows, widths) => {
    const render = (cells, header = false) => {
      doc.font(header ? 'Bold' : 'Regular').fontSize(9);
      const h = Math.max(
        27,
        ...cells.map((c, i) => doc.heightOfString(String(c), { width: widths[i] - 12 }) + 16),
      );
      if (doc.y + h > maxY) {
        doc.addPage();
        if (!header) render(headers, true);
      }
      doc.font(header ? 'Bold' : 'Regular').fontSize(9);
      const y = doc.y;
      let x = 42;
      if (header) doc.rect(42, y, 511, h).fill('#193E30');
      cells.forEach((c, i) => {
        doc
          .fillColor(header ? '#FFFFFF' : '#233C30')
          .text(String(c), x + 6, y + 8, { width: widths[i] - 12 });
        x += widths[i];
      });
      if (!header)
        doc
          .moveTo(42, y + h)
          .lineTo(553, y + h)
          .strokeColor('#E4E8DE')
          .stroke();
      doc.y = y + h;
    };
    render(headers, true);
    for (const row of rows) render(row);
    if (!rows.length) paragraph('No records yet.', { color: '#66725F' });
    doc.moveDown(0.4);
  };
  paragraph('Trip Expense Ledger', { size: 22, strong: true, color: '#193E30' });
  paragraph(trip.name, {size:14, strong:true});
  paragraph(`Exported ${new Date().toISOString()} · ${trip.currency} · Confirmed records`, {size:8,color:'#66725F'});
  paragraph('Transfers are recorded separately and excluded from shared expenses.', {size:8});
  const timestamp = ledgerDate;
  for (let start = 0; start < trip.members.length; start += 3) {
    const members = trip.members.slice(start,start+3);
    heading(start ? 'Shared expenses · shares continued' : 'Shared expenses');
    const memberWidth = 153 / Math.max(1,members.length);
    table(
      ['Bill date / logged UTC', 'Description / category', `Total (${trip.currency})`, 'Paid by', ...members.map(m => `${m.name}’s share`)],
      [...trip.expenses.map(e => [
        timestamp(e), `${e.title}\n${e.category}`, value(e.amount,trip.currency).toFixed(currencies[trip.currency]),
        e.payers.map(p => name(p.memberId)).join(', '),
        ...members.map(m => value(e.shares.find(s => s.memberId === m.id)?.amount || 0,trip.currency).toFixed(currencies[trip.currency])),
      ]), ['TOTAL', '', value(trip.total,trip.currency).toFixed(currencies[trip.currency]), '', ...members.map(m => value(trip.balances.find(b => b.id === m.id)?.spent || 0,trip.currency).toFixed(currencies[trip.currency]))]],
      [70,145,65,78, ...members.map(() => memberWidth)],
    );
  }
  heading('Settlement summary');
  table(['Member', 'Paid for bills', 'Share', 'Net balance'], trip.balances.map(b => [b.name,money(b.paid,trip.currency),money(b.spent,trip.currency),`${b.balance > 0 ? '+' : ''}${money(b.balance,trip.currency)}`]), [160,117,117,117]);
  for (const settlement of trip.settlements || []) {
    ensure(35);
    paragraph(`${name(settlement.from)} owes ${name(settlement.to)} ${money(settlement.amount,trip.currency)}`, {strong:true});
  }
  if (trip.transfers.length) {
    heading('Transfers · excluded from expenses');
    table(['Date / logged UTC','From / to','Amount','Note'],trip.transfers.map(t => [timestamp(t),`${name(t.from)} → ${name(t.to)}`,money(t.amount,trip.currency),t.note]),[70,174,117,150]);
  }
  if (analytics) {
    heading('Spending by category');
    const totals = {};
    for (const e of trip.expenses) totals[e.category] = (totals[e.category] || 0) + e.amount;
    for (const [category,total] of Object.entries(totals).sort((a,b)=>b[1]-a[1])) {
      ensure(55);
      paragraph(`${category} · ${money(total,trip.currency)} · ${Math.round(total/trip.total*100)}%`,{size:10});
      const y=doc.y+3;
      doc.roundedRect(42,y,511,9,4).fill('#E8EDE0');
      doc.roundedRect(42,y,Math.max(8,511*total/trip.total),9,4).fill('#285443');
      doc.y=y+25;
    }
  }
  const pages = doc.bufferedPageRange();
  for (let i = 0; i < pages.count; i++) {
    doc.switchToPage(i);
    const bottom = doc.page.margins.bottom;
    doc.page.margins.bottom = 0;
    doc
      .font('Regular')
      .fontSize(8)
      .fillColor('#66725F')
      .text(`SplitBill · ${i + 1} / ${pages.count}`, 42, 810, {
        width: 511,
        lineBreak: false,
        align: 'right',
      });
    doc.page.margins.bottom = bottom;
  }
  doc.end();
  return complete;
}


// Google credentials stay in Supabase. The app sends only a one-use PKCE code.
function createGoogleAuth({ url = process.env.SUPABASE_URL, key = process.env.SUPABASE_ANON_KEY, request = fetch } = {}) {
  const call = async (path, options = {}) => {
    assert(url && key, 'Google sign-in needs the SplitBill cloud connection.', 503);
    const response = await request(`${url}/auth/v1/${path}`, {
      ...options,
      headers: { apikey: key, 'Content-Type': 'application/json', ...options.headers },
      signal: AbortSignal.timeout(12000),
    });
    const data = await response.json();
    assert(response.ok, response.status === 429
      ? 'Too many sign-in attempts. Try again later.'
      : 'Google sign-in could not be verified. Please start again.', response.status === 429 ? 429 : 401);
    return data;
  };
  return {
    config: async () => {
      const settings = await call('settings');
      assert(settings.external?.google, 'Google sign-in is not configured yet. Please try again after setup is complete.', 503);
      return { authorizeUrl: `${url}/auth/v1/authorize` };
    },
    exchange: async (code, verifier) => {
      assert(typeof code === 'string' && code.length > 0 && code.length <= 2048, 'Start Google sign-in again');
      assert(typeof verifier === 'string' && /^[A-Za-z0-9._~-]{43,128}$/.test(verifier), 'Start Google sign-in again');
      const session = await call('token?grant_type=pkce', {
        method: 'POST', body: JSON.stringify({ auth_code: code, code_verifier: verifier }),
      });
      assert(session.access_token, 'Google sign-in could not be verified', 401);
      const user = await call('user', { headers: { Authorization: `Bearer ${session.access_token}` } });
      const identity = user.identities?.find(item => item.provider === 'google');
      const details = identity?.identity_data;
      assert(details?.sub && details.email_verified === true && user.email_confirmed_at,
        'Use a verified Google account to continue', 401);
      const email = String(details.email || '').trim().toLowerCase();
      assert(email === user.email?.toLowerCase() && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email), 'Google email could not be verified', 401);
      // Identity metadata supplies presentation only, never roles or app ownership.
      let photo = '';
      try {
        const avatar = new URL(details.picture || details.avatar_url || '');
        if (avatar.protocol === 'https:' && (avatar.hostname === 'googleusercontent.com' || avatar.hostname.endsWith('.googleusercontent.com')) && !avatar.username && !avatar.password && avatar.href.length < 2048) photo = avatar.href;
      } catch { /* Google accounts without a photo use initials. */ }
      return { photo, subject: String(details.sub), email, name: String(details.full_name || details.name || 'Friend').trim().slice(0, 60) || 'Friend' };
    },
  };
}


function getAiConfig(env = process.env) {
  const geminiKey = String(env.GEMINI_API_KEY || '').trim();
  const openaiKey = String(env.OPENAI_API_KEY || '').trim();
  const geminiModel = String(env.GEMINI_MODEL || 'gemini-2.5-flash').trim();
  const openaiModel = String(env.OPENAI_MODEL || 'gpt-4o-mini').trim();
  const openaiBaseUrl = String(env.OPENAI_BASE_URL || 'https://api.openai.com/v1').trim().replace(/\/+$/, '');
  const timeoutMs = Math.max(5000, Math.min(60000, Number(env.AI_TIMEOUT_MS || 25000)));
  return {
    configured: Boolean(geminiKey || openaiKey),
    provider: geminiKey ? 'gemini' : openaiKey ? 'openai' : 'none',
    model: geminiKey ? geminiModel : openaiKey ? openaiModel : 'none',
    geminiKey,
    geminiModel,
    openaiKey,
    openaiBaseUrl,
    openaiModel,
    timeoutMs,
  };
}

function extractJsonObject(rawText) {
  const cleaned = String(rawText || '').trim();
  const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1].trim() : cleaned;
  const firstBrace = candidate.indexOf('{');
  const lastBrace = candidate.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    return JSON.parse(candidate.slice(firstBrace, lastBrace + 1));
  }
  return JSON.parse(candidate);
}

function createAiClient({ env = process.env, request = fetch } = {}) {
  const cfg = getAiConfig(env);

  const generateJson = async ({ systemInstruction, prompt, attachment = null, temperature = 0.2 }) => {
    const current = getAiConfig(env);
    if (!current.configured) {
      return { ok: false, reason: 'AI_NOT_CONFIGURED', data: null };
    }
    try {
      if (current.provider === 'gemini') {
        const parts = [];
        if (attachment && attachment.data && attachment.mime) {
          parts.push({
            inline_data: {
              mime_type: attachment.mime,
              data: attachment.data,
            },
          });
        }
        parts.push({ text: prompt });

        const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(current.geminiModel)}:generateContent?key=${encodeURIComponent(current.geminiKey)}`;
        const response = await request(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            system_instruction: { parts: [{ text: systemInstruction }] },
            contents: [{ role: 'user', parts }],
            generationConfig: {
              temperature,
              responseMimeType: 'application/json',
            },
          }),
          signal: AbortSignal.timeout(current.timeoutMs),
        });
        const payload = await response.json();
        if (!response.ok) {
          return {
            ok: false,
            reason: payload?.error?.message || `Gemini API HTTP ${response.status}`,
            data: null,
          };
        }
        const textOut = payload?.candidates?.[0]?.content?.parts?.map((p) => p.text || '').join('') || '';
        return { ok: true, provider: 'gemini', model: current.geminiModel, data: extractJsonObject(textOut) };
      }

      if (current.provider === 'openai') {
        const userContent = [{ type: 'text', text: prompt }];
        if (attachment && attachment.data && attachment.mime && attachment.mime.startsWith('image/')) {
          userContent.push({
            type: 'image_url',
            image_url: { url: `data:${attachment.mime};base64,${attachment.data}` },
          });
        }
        const response = await request(`${current.openaiBaseUrl}/chat/completions`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${current.openaiKey}`,
          },
          body: JSON.stringify({
            model: current.openaiModel,
            temperature,
            response_format: { type: 'json_object' },
            messages: [
              { role: 'system', content: systemInstruction },
              { role: 'user', content: userContent },
            ],
          }),
          signal: AbortSignal.timeout(current.timeoutMs),
        });
        const payload = await response.json();
        if (!response.ok) {
          return {
            ok: false,
            reason: payload?.error?.message || `OpenAI API HTTP ${response.status}`,
            data: null,
          };
        }
        const textOut = payload?.choices?.[0]?.message?.content || '';
        return { ok: true, provider: 'openai', model: current.openaiModel, data: extractJsonObject(textOut) };
      }
      return { ok: false, reason: 'AI_NOT_CONFIGURED', data: null };
    } catch (error) {
      return {
        ok: false,
        reason: error?.name === 'TimeoutError' ? 'AI provider request timed out' : String(error?.message || 'AI request failed'),
        data: null,
      };
    }
  };

  return {
    status: () => ({
      configured: cfg.configured,
      provider: cfg.provider,
      model: cfg.model,
    }),
    generateJson,
  };
}


const VALID_CATEGORIES = [
  'Food & drinks', 'Transport', 'Stay', 'Shopping', 'Activities',
  'Groceries', 'Bills', 'Fuel', 'Tickets', 'Rentals', 'Fees & tips', 'Health', 'Other',
];

const KEYWORD_RULES = [
  { cat: 'Food & drinks', re: /dinner|lunch|breakfast|cafe|coffee|zomato|swiggy|restaurant|pizza|burger|bar|drinks|tea|biryani|chai/i },
  { cat: 'Transport', re: /uber|ola|cab|taxi|auto|metro|train|irctc|flight|indigo|bus|toll|parking/i },
  { cat: 'Stay', re: /hotel|airbnb|oyo|hostel|resort|villa|stay|room|booking\.com/i },
  { cat: 'Groceries', re: /blinkit|zepto|instamart|bigbasket|dmart|grocery|supermarket|milk|vegetables|fruits/i },
  { cat: 'Fuel', re: /petrol|diesel|fuel|hpcl|bpcl|iocl|shell|cng/i },
  { cat: 'Tickets', re: /movie|pvr|inox|bookmyshow|ticket|concert|museum|entry/i },
  { cat: 'Bills', re: /electricity|wifi|broadband|airtel|jio|water|gas|rent|utility/i },
  { cat: 'Health', re: /pharmacy|apollo|medplus|doctor|hospital|medicine|clinic/i },
  { cat: 'Shopping', re: /amazon|flipkart|myntra|mall|zara|clothes|store/i },
];

function inferCategoryDeterministic(text = '') {
  for (const rule of KEYWORD_RULES) {
    if (rule.re.test(text)) return { category: rule.cat, confidence: 0.86 };
  }
  return { category: 'Other', confidence: 0.45 };
}

async function analyzeReceipt({ file, trip, aiClient = createAiClient() }) {
  assert(file && typeof file.data === 'string' && file.data.length > 0, 'Receipt file data is required');
  assert(['image/jpeg', 'image/png', 'image/webp', 'application/pdf'].includes(file.mime), 'Unsupported receipt format');
  const fileHash = createHash('sha256').update(file.data).digest('hex');

  const systemInstruction = `You are a precision financial receipt OCR and extraction engine.
Extract structured data from the provided receipt image or PDF.
Return ONLY valid JSON matching:
{
  "merchant": string,
  "date": "YYYY-MM-DD" or null,
  "currency": "${trip.currency}" or detected 3-letter ISO code,
  "category": one of ${JSON.stringify(VALID_CATEGORIES)},
  "items": [{ "name": string, "quantity": number, "unitPrice": number, "totalPrice": number }],
  "subtotal": number,
  "tax": number,
  "discount": number,
  "total": number,
  "missingFields": string[],
  "confidence": number between 0 and 1
}`;

  const aiResult = await aiClient.generateJson({
    systemInstruction,
    prompt: `Extract all line items, quantities, unit prices, taxes, discounts, merchant name, date, and final total. Group currency is ${trip.currency}.`,
    attachment: { mime: file.mime, data: file.data },
    temperature: 0.1,
  });

  if (!aiResult.ok) {
    const inferred = inferCategoryDeterministic(file.name || '');
    return {
      status: aiResult.reason === 'AI_NOT_CONFIGURED' ? 'needs_api_key' : 'fallback',
      message: aiResult.reason === 'AI_NOT_CONFIGURED'
        ? 'Set GEMINI_API_KEY on the server to enable automatic vision/PDF line-item OCR. You can enter or edit items manually below.'
        : `Vision service unavailable (${aiResult.reason}). Fill or adjust fields below.`,
      fileHash,
      merchant: (file.name || 'Receipt').replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' '),
      date: new Date().toISOString().slice(0, 10),
      currency: trip.currency,
      category: inferred.category,
      items: [],
      subtotal: 0,
      tax: 0,
      discount: 0,
      total: 0,
      mathValidation: { valid: true, discrepancy: 0, warnings: ['Manual entry required without vision API key'] },
      confidence: 0,
    };
  }

  const parsed = aiResult.data || {};
  const items = Array.isArray(parsed.items)
    ? parsed.items.map((it, idx) => ({
        id: `item_${idx + 1}`,
        name: String(it.name || `Item ${idx + 1}`).slice(0, 80),
        quantity: Number(it.quantity) > 0 ? Number(it.quantity) : 1,
        unitPrice: Number(it.unitPrice) || 0,
        totalPrice: Number(it.totalPrice) || (Number(it.quantity || 1) * Number(it.unitPrice || 0)),
        assignedTo: trip.members.map((m) => m.id),
      }))
    : [];

  const itemsSum = Number(items.reduce((acc, it) => acc + it.totalPrice, 0).toFixed(2));
  const tax = Number(parsed.tax) || 0;
  const discount = Number(parsed.discount) || 0;
  const total = Number(parsed.total) || Number((itemsSum + tax - discount).toFixed(2));
  const expectedTotal = Number((itemsSum + tax - discount).toFixed(2));
  const discrepancy = items.length > 0 ? Number((total - expectedTotal).toFixed(2)) : 0;

  const warnings = [];
  if (Math.abs(discrepancy) > 0.05) {
    warnings.push(`Receipt total (${total}) differs from items + tax - discount (${expectedTotal}) by ${discrepancy}. Verify before saving.`);
  }
  if (!parsed.date) warnings.push('Receipt date was unclear; defaulted to today.');
  if (!parsed.merchant) warnings.push('Merchant name was not detected.');

  const category = VALID_CATEGORIES.includes(parsed.category)
    ? parsed.category
    : inferCategoryDeterministic(`${parsed.merchant || ''} ${items.map((i) => i.name).join(' ')}`).category;

  return {
    status: 'extracted',
    provider: aiResult.provider,
    model: aiResult.model,
    fileHash,
    merchant: String(parsed.merchant || 'Scanned Receipt').slice(0, 120),
    date: /^\d{4}-\d{2}-\d{2}$/.test(String(parsed.date || '')) ? parsed.date : new Date().toISOString().slice(0, 10),
    currency: Object.hasOwn(currencies, parsed.currency) ? parsed.currency : trip.currency,
    category,
    items,
    subtotal: itemsSum,
    tax,
    discount,
    total,
    mathValidation: {
      valid: Math.abs(discrepancy) <= 0.05,
      expectedTotal,
      discrepancy,
      warnings,
    },
    confidence: Math.max(0, Math.min(1, Number(parsed.confidence) || 0.85)),
  };
}

function computeItemizedShares(items, tax, discount, total, members, currency) {
  const scale = 10 ** currencies[currency];
  const memberWeights = Object.fromEntries(members.map((m) => [m.id, 0]));
  for (const item of items) {
    const assignees = (item.assignedTo || []).filter((id) => Object.hasOwn(memberWeights, id));
    if (!assignees.length) continue;
    const perPerson = (Number(item.totalPrice) || 0) / assignees.length;
    for (const id of assignees) memberWeights[id] += perPerson;
  }
  const activeMembers = members.filter((m) => memberWeights[m.id] > 0);
  assert(activeMembers.length > 0, 'Assign at least one item to a group member');
  const totalMinor = minor(String(Number(total).toFixed(currencies[currency])), currency);
  const allocated = allocate(
    totalMinor,
    activeMembers.map((m) => memberWeights[m.id]),
  );
  return activeMembers.map((m, idx) => ({
    memberId: m.id,
    amountMinor: allocated[idx],
    value: (allocated[idx] / scale).toFixed(currencies[currency]),
  }));
}

function detectExpenseAnomalies({ candidate, trip, receiptAnalysis = null }) {
  const flags = [];
  let riskScore = 0;
  const currency = candidate.currency || trip.currency;
  const scale = 10 ** currencies[currency];
  const candidateMinor = minor(String(candidate.amount), currency);
  const candidateMajor = candidateMinor / scale;

  for (const existing of trip.expenses) {
    if (candidate.id && existing.id === candidate.id) continue;
    const sameAmount = existing.originalAmount === candidateMinor && existing.currency === currency;
    const sameDate = existing.date === candidate.date;
    const titleSim = existing.title.trim().toLowerCase() === String(candidate.title || '').trim().toLowerCase();

    if (sameAmount && sameDate && titleSim) {
      riskScore += 0.55;
      flags.push({
        code: 'EXACT_DUPLICATE',
        severity: 'high',
        reason: `An identical bill ("${existing.title}" for ${currency} ${candidateMajor.toFixed(2)} on ${existing.date}) already exists in this group.`,
      });
    } else if (sameAmount && sameDate) {
      riskScore += 0.35;
      flags.push({
        code: 'SAME_DAY_AMOUNT',
        severity: 'medium',
        reason: `Another expense of ${currency} ${candidateMajor.toFixed(2)} was already logged on ${existing.date} ("${existing.title}").`,
      });
    }
    if (receiptAnalysis?.fileHash && existing.receiptHash === receiptAnalysis.fileHash) {
      riskScore += 0.65;
      flags.push({
        code: 'DUPLICATE_RECEIPT_FILE',
        severity: 'high',
        reason: `This exact receipt file was already attached to "${existing.title}" on ${existing.date}.`,
      });
    }
  }

  if (receiptAnalysis && receiptAnalysis.total > 0) {
    const diff = Math.abs(candidateMajor - receiptAnalysis.total);
    if (diff > Math.max(1, receiptAnalysis.total * 0.02)) {
      riskScore += 0.4;
      flags.push({
        code: 'RECEIPT_AMOUNT_MISMATCH',
        severity: 'high',
        reason: `Entered amount (${currency} ${candidateMajor.toFixed(2)}) differs from scanned receipt total (${receiptAnalysis.currency} ${receiptAnalysis.total.toFixed(2)}).`,
      });
    }
    if (receiptAnalysis.date && candidate.date && receiptAnalysis.date !== candidate.date) {
      riskScore += 0.2;
      flags.push({
        code: 'RECEIPT_DATE_MISMATCH',
        severity: 'low',
        reason: `Entered date (${candidate.date}) differs from the date printed on the receipt (${receiptAnalysis.date}).`,
      });
    }
  }

  if (trip.expenses.length >= 4) {
    const amounts = trip.expenses.map((e) => e.amount / scale);
    const mean = amounts.reduce((a, b) => a + b, 0) / amounts.length;
    const variance = amounts.reduce((a, b) => a + (b - mean) ** 2, 0) / amounts.length;
    const stdDev = Math.sqrt(variance);
    if (stdDev > 0 && candidateMajor > mean + 3 * stdDev && candidateMajor > mean * 2.5) {
      riskScore += 0.3;
      flags.push({
        code: 'UNUSUAL_AMOUNT_SPIKE',
        severity: 'medium',
        reason: `Amount (${currency} ${candidateMajor.toFixed(2)}) is significantly higher than this group's typical expense average (${currency} ${mean.toFixed(2)}).`,
      });
    }
  }

  const confidence = Number(Math.min(0.99, riskScore).toFixed(2));
  return {
    flagged: flags.length > 0,
    confidence,
    level: confidence >= 0.6 ? 'high' : confidence >= 0.3 ? 'medium' : 'none',
    summary: flags.length
      ? 'Potential anomaly detected — please review before saving.'
      : 'No duplicate or consistency issues detected.',
    flags,
  };
}

function forecastGroupSpending({ trip, budgets = {} }) {
  const scale = 10 ** currencies[trip.currency];
  const now = new Date();
  const currentMonth = now.toISOString().slice(0, 7);
  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const dayOfMonth = Math.max(1, now.getDate());

  const byMonth = {};
  const currentMonthByCategory = {};
  const historicalByCategory = {};

  for (const exp of trip.expenses) {
    const month = String(exp.date || '').slice(0, 7);
    const major = exp.amount / scale;
    byMonth[month] = (byMonth[month] || 0) + major;
    if (month === currentMonth) {
      currentMonthByCategory[exp.category] = (currentMonthByCategory[exp.category] || 0) + major;
    } else {
      historicalByCategory[exp.category] = (historicalByCategory[exp.category] || 0) + major;
    }
  }

  const pastMonths = Object.keys(byMonth).filter((m) => m !== currentMonth).sort();
  const pastAvg = pastMonths.length
    ? pastMonths.reduce((s, m) => s + byMonth[m], 0) / pastMonths.length
    : 0;
  const currentSpend = byMonth[currentMonth] || 0;
  const paceProjection = (currentSpend / dayOfMonth) * daysInMonth;
  const predictedMonthTotal = pastAvg > 0
    ? Number((0.6 * paceProjection + 0.4 * pastAvg).toFixed(2))
    : Number(paceProjection.toFixed(2));

  const categoryInsights = Object.entries(currentMonthByCategory)
    .map(([category, spent]) => {
      const projected = Number(((spent / dayOfMonth) * daysInMonth).toFixed(2));
      const budgetLimit = budgets[category] ? budgets[category] / scale : null;
      return {
        category,
        spentToDate: Number(spent.toFixed(2)),
        projectedMonthly: projected,
        budgetLimit,
        overBudgetRisk: budgetLimit ? projected > budgetLimit : false,
        explanation: `You have spent ${trip.currency} ${spent.toLocaleString('en-IN')} on ${category} this month. Based on current pace, predicted monthly ${category.toLowerCase()} spend is ${trip.currency} ${projected.toLocaleString('en-IN')}.`,
      };
    })
    .sort((a, b) => b.projectedMonthly - a.projectedMonthly);

  const recommendations = [];
  for (const item of categoryInsights.slice(0, 2)) {
    if (item.overBudgetRisk && item.budgetLimit) {
      recommendations.push(
        `Trim ${item.category} spending by ${trip.currency} ${Math.ceil((item.projectedMonthly - item.budgetLimit) / Math.max(1, daysInMonth - dayOfMonth))}/day to stay within your ${trip.currency} ${item.budgetLimit} budget.`
      );
    } else if (item.projectedMonthly > 0) {
      recommendations.push(
        `Batching ${item.category.toLowerCase()} orders could save ~10% (${trip.currency} ${Math.round(item.projectedMonthly * 0.1)}) by month-end.`
      );
    }
  }

  const confidence = trip.expenses.length >= 10 ? 0.86 : trip.expenses.length >= 3 ? 0.72 : 0.54;
  return {
    currency: trip.currency,
    currentMonth,
    spentThisMonth: Number(currentSpend.toFixed(2)),
    predictedMonthTotal,
    historicalMonthlyAverage: Number(pastAvg.toFixed(2)),
    confidence,
    monthlySeries: Object.entries(byMonth)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([month, total]) => ({ month, total: Number(total.toFixed(2)) })),
    categoryInsights,
    recommendations,
  };
}

async function runConversationalAgent({ message, history = [], trip, user, aiClient = createAiClient() }) {
  const promptText = String(message || '').trim();
  assert(promptText.length > 0 && promptText.length <= 1000, 'Enter a message up to 1000 characters');

  const scale = 10 ** currencies[trip.currency];
  const meMember = trip.members.find((m) => m.id === trip.me);
  const memberDirectory = trip.members.map((m) => ({
    id: m.id,
    name: m.name,
    balance: (trip.balances.find((b) => b.id === m.id)?.balance || 0) / scale,
  }));

  const proactiveSuggestions = [];
  const miscategorized = trip.expenses.filter(
    (e) => e.category === 'Other' && inferCategoryDeterministic(e.title).category !== 'Other'
  );
  if (miscategorized.length > 0) {
    const sample = miscategorized[0];
    const suggestedCat = inferCategoryDeterministic(sample.title).category;
    proactiveSuggestions.push({
      type: 'recategorize',
      expenseId: sample.id,
      title: `Re-categorize "${sample.title}" to ${suggestedCat}`,
      reason: `"${sample.title}" is currently under Other, but matches ${suggestedCat}.`,
      requiresConfirmation: true,
    });
  }
  if (trip.settlements.length > 0) {
    const top = trip.settlements[0];
    const fromName = trip.members.find((m) => m.id === top.from)?.name || 'Member';
    const toName = trip.members.find((m) => m.id === top.to)?.name || 'Member';
    proactiveSuggestions.push({
      type: 'settlement_reminder',
      title: `Settle up ${trip.currency} ${(top.amount / scale).toFixed(2)} (${fromName} → ${toName})`,
      reason: `${fromName} has the largest outstanding balance in "${trip.name}".`,
      requiresConfirmation: true,
    });
  }

  const addMatch = promptText.match(/(?:add|log|record|split)\s+(?:₹|rs\.?|inr|\$|€|£)?\s*(\d+(?:\.\d{1,2})?)\s+(.+?)(?:\s+(?:between|with|among|for)\s+(.+))?$/i);
  if (addMatch && !aiClient.status().configured) {
    const rawAmount = addMatch[1];
    const rawTitle = addMatch[2].replace(/\s+expense$/i, '').trim();
    const inferred = inferCategoryDeterministic(rawTitle);
    const targetText = (addMatch[3] || '').toLowerCase();
    let shareMembers = trip.members;
    if (targetText && !/all|everyone/.test(targetText)) {
      const matched = trip.members.filter((m) => targetText.includes(m.name.toLowerCase().split(' ')[0]));
      if (matched.length > 0) {
        shareMembers = matched.some((m) => m.id === trip.me) ? matched : [meMember, ...matched].filter(Boolean);
      }
    }
    return {
      reply: `I prepared a draft for "${rawTitle}" (${trip.currency} ${rawAmount}) split equally among ${shareMembers.map((m) => m.name).join(', ')}. Review and confirm to save.`,
      requiresConfirmation: true,
      draftExpense: {
        title: rawTitle.charAt(0).toUpperCase() + rawTitle.slice(1),
        amount: rawAmount,
        currency: trip.currency,
        rate: 1,
        date: new Date().toISOString().slice(0, 10),
        category: inferred.category,
        note: 'Created via SplitBill AI Assistant',
        mode: 'equal',
        payers: [{ memberId: trip.me, amount: rawAmount }],
        shares: shareMembers.map((m) => ({ memberId: m.id, value: '0' })),
      },
      proactiveSuggestions,
    };
  }

  if (!aiClient.status().configured) {
    if (/highest|most|owes/i.test(promptText)) {
      const sorted = [...memberDirectory].sort((a, b) => a.balance - b.balance);
      const topDebtor = sorted[0];
      const topCreditor = sorted[sorted.length - 1];
      return {
        reply: topDebtor && topDebtor.balance < 0
          ? `${topDebtor.name} has the highest outstanding balance to pay (${trip.currency} ${Math.abs(topDebtor.balance).toFixed(2)}), while ${topCreditor.name} is owed ${trip.currency} ${topCreditor.balance.toFixed(2)}.`
          : `Everyone in ${trip.name} is currently settled up!`,
        requiresConfirmation: false,
        proactiveSuggestions,
      };
    }
    const totalMajor = trip.total / scale;
    return {
      reply: `"${trip.name}" has ${trip.expenses.length} expenses totaling ${trip.currency} ${totalMajor.toFixed(2)}. Your personal net balance is ${trip.currency} ${((meMember ? trip.balances.find((b) => b.id === trip.me)?.balance : 0) / scale).toFixed(2)}.`,
      requiresConfirmation: false,
      proactiveSuggestions,
    };
  }

  const systemInstruction = `You are SplitBill AI, an autonomous expense management assistant scoped strictly to the user's current group "${trip.name}" (${trip.currency}).
Logged-in user: ${user.name} (memberId: ${trip.me}).
Group members & current net balances (${trip.currency}): ${JSON.stringify(memberDirectory)}.
Recent expenses: ${JSON.stringify(trip.expenses.slice(-25).map((e) => ({ id: e.id, title: e.title, amount: e.amount / scale, category: e.category, date: e.date })))}.

Rules:
1. Never invent balances or expenses outside the provided group data.
2. If the user asks to create/add/split an expense, DO NOT claim it is saved; set "requiresConfirmation": true and return "draftExpense".
3. Return ONLY valid JSON:
{
  "reply": string,
  "requiresConfirmation": boolean,
  "draftExpense": null | {
    "title": string,
    "amount": string,
    "currency": "${trip.currency}",
    "rate": 1,
    "date": "YYYY-MM-DD",
    "category": one of ${JSON.stringify(VALID_CATEGORIES)},
    "note": string,
    "mode": "equal" | "exact" | "percent" | "shares",
    "payers": [{ "memberId": string, "amount": string }],
    "shares": [{ "memberId": string, "value": string }]
  }
}`;

  const llm = await aiClient.generateJson({
    systemInstruction,
    prompt: `Conversation history: ${JSON.stringify(history.slice(-6))}\nUser message: ${promptText}`,
    temperature: 0.2,
  });

  if (!llm.ok) {
    return {
      reply: `I couldn't reach the AI model (${llm.reason}), but your group "${trip.name}" currently has ${trip.expenses.length} bills totaling ${trip.currency} ${(trip.total / scale).toFixed(2)}.`,
      requiresConfirmation: false,
      proactiveSuggestions,
    };
  }

  return {
    reply: String(llm.data?.reply || 'Done.'),
    requiresConfirmation: Boolean(llm.data?.requiresConfirmation && llm.data?.draftExpense),
    draftExpense: llm.data?.draftExpense || null,
    proactiveSuggestions,
  };
}


const derive = promisify(scrypt);
const inputText = (value, label, max = 120) => {
  const s = String(value ?? '').trim();
  assert(s.length > 0 && s.length <= max, `${label} must contain 1–${max} characters`);
  return s;
};
const date = (value) => {
  assert(
    typeof value === 'string' &&
      /^\d{4}-\d{2}-\d{2}$/.test(value) &&
      Number.isFinite(Date.parse(value)) &&
      new Date(value).toISOString().slice(0, 10) === value,
    'Use a valid date (YYYY-MM-DD)',
  );
  return value;
};
const inputEmail = (value) =>
  String(value || '')
    .trim()
    .toLowerCase();
const id = () => randomUUID();
const clientId = (value) => (value && /^[a-zA-Z0-9_-]{16,100}$/.test(value) ? value : id());
const hash = (token) => createHash('sha256').update(token).digest('hex');
const canonical = (value) =>
  Array.isArray(value)
    ? value.map(canonical)
    : value && typeof value === 'object'
      ? Object.fromEntries(
          Object.keys(value)
            .sort()
            .map((key) => [key, canonical(value[key])]),
        )
      : value;
const requestSignature = (body) =>
  hash(JSON.stringify(canonical({ ...body, clientRequestId: undefined })));
const categories = [
  'Food & drinks',
  'Transport',
  'Stay',
  'Shopping',
  'Activities',
  'Groceries',
  'Bills',
  'Fuel',
  'Tickets',
  'Rentals',
  'Fees & tips',
  'Health',
  'Other',
];

function createHandler(db, attempts = new Map(), googleAuth = createGoogleAuth(), { allowLegacyAuth = false } = {}) {
  const throttle = (key, limit = 20) => {
    const now = Date.now();
    let a = attempts.get(key);
    if (!a || a.until < now) {
      a = { count: 0, until: now + 600_000 };
      attempts.set(key, a);
    }
    assert(++a.count <= limit, 'Too many attempts. Please try again in 10 minutes.', 429);
    if (attempts.size > 10000) for (const [k, v] of attempts) if (v.until < now) attempts.delete(k);
  };
  const save = async (trip) => {
    trip.version = (trip.version || 0) + 1;
    trip.updatedAt = new Date().toISOString();
    await db
      .prepare('INSERT INTO trips VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data')
      .run(trip.id, trip.code, JSON.stringify(trip));
  };
  const newUsername = async (name) => {
    const base = String(name || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 4) || 'user';
    for (let attempt = 0; attempt < 100; attempt++) {
      const username = attempt < 20
        ? `${base}${String(randomBytes(4).readUInt32BE() % 10000).padStart(4, '0')}`
        : randomBytes(4).toString('hex');
      if (!(await db.prepare('SELECT user_id FROM profiles WHERE username=?').get(username))) return username;
    }
    throw Object.assign(new Error('Could not assign a username. Please try again.'), {status:503});
  };
  const publicUser = async (user) => {
    let profile=await db.prepare('SELECT username,photo FROM profiles WHERE user_id=?').get(user.id);
    if (!profile) {
      // Older device identities predate usernames; preserve their ID and group access.
      const username = await newUsername(user.name);
      await db.prepare('INSERT INTO profiles(user_id,username,photo) VALUES(?,?,?)').run(user.id,username,'');
      profile={username,photo:''};
    }
    return {
      googleEmail:(await db.prepare("SELECT email FROM oauth_identities WHERE user_id=? AND provider='google'").get(user.id))?.email || '',
      ...profile,id:user.id,name:user.name,
      email:user.email.endsWith('@guest.splitly.local') ? '' : user.email,
      guest:user.email.endsWith('@guest.splitly.local'),
    };
  };
  const googleAccount = async (identity, currentUser) => {
    const linked = await db.prepare("SELECT user_id FROM oauth_identities WHERE provider='google' AND subject=?").get(identity.subject);
    if (currentUser) {
      assert(!linked || linked.user_id === currentUser.id, 'This Google account is already connected to another SplitBill account.', 409);
      const own = await db.prepare("SELECT subject FROM oauth_identities WHERE user_id=? AND provider='google'").get(currentUser.id);
      assert(!own || own.subject === identity.subject, 'This SplitBill account already has a different Google account connected.', 409);
    }
    let user = currentUser || (linked && await db.prepare('SELECT * FROM users WHERE id=?').get(linked.user_id));
    if (!user) {
      const userId = id();
      user = { id: userId, email: `guest-${userId}@guest.splitly.local`, name: identity.name, salt: randomBytes(16).toString('hex'), password: randomBytes(64).toString('hex') };
      await db.prepare('INSERT INTO users VALUES(?,?,?,?,?)').run(user.id,user.email,user.name,user.salt,user.password);
      const username = await newUsername(identity.name);
      await db.prepare('INSERT INTO profiles(user_id,username,photo) VALUES(?,?,?)').run(user.id,username,identity.photo || '');
    }
    if (!linked) await db.prepare('INSERT INTO oauth_identities(provider,subject,user_id,email) VALUES(?,?,?,?)').run('google',identity.subject,user.id,identity.email);
    else await db.prepare("UPDATE oauth_identities SET email=? WHERE provider='google' AND subject=?").run(identity.email,identity.subject);
    return user;
  };
  const decorate = async (trip, user) => {
    const decoratedMembers = await Promise.all(
      trip.members.map(async ({ userId, ...m }) => ({
        ...m,
        linked: Boolean(userId),
        ...(userId
          ? (await db.prepare('SELECT username,photo FROM profiles WHERE user_id=?').get(userId)) ||
            {}
          : {}),
      })),
    );
    return {
      id: trip.id,
      name: trip.name,
      code: trip.code,
      currency: trip.currency,
      categories: [...categories, ...(trip.categories || [])],
      ownerId: trip.ownerId,
      version: trip.version || 0,
      updatedAt: trip.updatedAt,
      me: trip.members.find((m) => m.userId === user.id)?.id,
      isOwner: trip.ownerId === user.id,
      members: decoratedMembers,
      expenses: trip.expenses.map(({ receipt, ...expense }) => expense),
      transfers: trip.transfers,
      activity: trip.activity || [],
      balances: balances(trip).map(({ userId, ...m }) => ({
        ...m,
        ...decoratedMembers.find((p) => p.id === m.id),
      })),
      settlements: settlements(trip),
      total: trip.expenses.reduce((a, e) => a + e.amount, 0),
    };
  };
  const snapshots = new WeakMap();
  const resolvePerson = async (value, usernameValue, emailValue) => {
    const raw = String(value || '').trim();
    const username = String(usernameValue || (raw.startsWith('@') ? raw.slice(1) : '')).trim().toLowerCase();
    if (username || raw.startsWith('@')) {
      assert(/^[a-z0-9_]{3,24}$/.test(username), 'Use @ followed by a valid username');
      const account = await db.prepare('SELECT users.id,users.name FROM profiles JOIN users ON users.id=profiles.user_id WHERE profiles.username=?').get(username);
      assert(account, `No account found for @${username}. Check the username or add a guest by name.`);
      return {name:account.name,userId:account.id};
    }
    if (emailValue) {
      const account=await db.prepare('SELECT id,name FROM users WHERE email=?').get(String(emailValue).trim().toLowerCase());
      assert(account,'No account with this email. Add a guest by name or share the invite code.');
      return {name:account.name,userId:account.id};
    }
    return {name:inputText(raw,'Member name',60)};
  };
  const event = (trip, user, message) => {
    const after = auditSnapshot(trip);
    const changes = auditChanges(snapshots.get(trip) || {}, after);
    trip.activity ||= [];
    trip.activity.unshift({
      id: id(),
      user: user.name,
      userId: user.id,
      message,
      changes,
      at: new Date().toISOString(),
    });
    snapshots.set(trip, after);
  };
  return async (req, res) => {
    let operation = null;
    const send = async (status, data) => {
      if (operation && status >= 200 && status < 300)
        await db
          .prepare('INSERT INTO operations VALUES(?,?,?,?,?)')
          .run(
            operation.userId,
            operation.id,
            operation.path,
            operation.signature,
            JSON.stringify(
              data?.members
                ? { id: data.id, members: [] }
                : data?.guest !== undefined
                  ? { profile: true }
                  : { ok: true },
            ),
          );
      res.writeHead(status, {
        'Content-Type': 'application/json',
        'Cache-Control': 'no-store',
        'X-Content-Type-Options': 'nosniff',
      });
      res.end(JSON.stringify(data));
    };
    const origin = req.headers.origin;
    if (
      origin &&
      /^(https?:\/\/)(localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+)(:\d+)?$/.test(
        origin,
      )
    ) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Vary', 'Origin');
      res.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type');
      res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
    }
    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      return res.end();
    }
    try {
      const url = new URL(req.url, 'http://localhost');
      const segments = url.pathname.split('/').filter(Boolean);
      assert(segments[0] === 'api', 'Not found', 404);
      if (url.pathname === '/api/health')
        return await send(200, { ok: true, service: 'SplitBill API' });
      if (url.pathname === '/api/google/config' && req.method === 'GET')
        return await send(200, await googleAuth.config());
      let body = {};
      if (['POST', 'PATCH', 'DELETE'].includes(req.method)) {
        assert(
          (req.headers['content-type'] || '').includes('application/json'),
          'JSON body required',
          415,
        );
        let raw = '',
          size = 0;
        for await (const chunk of req) {
          size += chunk.length;
          assert(size <= 3_000_000, 'Request is too large', 413);
          raw += chunk;
        }
        try {
          body = !raw && req.method === 'DELETE' ? {} : JSON.parse(raw);
        } catch {
          assert(false, 'Invalid JSON');
        }
        assert(body && typeof body === 'object' && !Array.isArray(body), 'Invalid request body');
      }
      if (url.pathname === '/api/google/login' && req.method === 'POST') {
        throttle(`google:${req.socket.remoteAddress}`, 15);
        const recovered = await googleAccount(await googleAuth.exchange(body.code, body.verifier));
        const session = randomBytes(32).toString('hex');
        await db.prepare('INSERT INTO sessions VALUES(?,?,?)').run(hash(session), recovered.id, Date.now()+3650*86400_000);
        return await send(200, {token:session,user:await publicUser(recovered)});
      }
      if (['email-login', 'backup-email'].includes(segments[1]))
        return await send(410, { error: 'Email sign-in has been replaced by Google. Update SplitBill and continue with Google.' });
      if (['guest', 'register', 'login'].includes(segments[1]) && !allowLegacyAuth)
        return await send(410, { error: 'Continue with Google to create or restore your SplitBill account.' });
      if (segments[1] === 'guest' && req.method === 'POST') {
        throttle(`auth:${req.socket.remoteAddress}`);
        const username = String(body.username || `user_${randomBytes(6).toString('hex')}`)
          .trim()
          .toLowerCase();
        assert(
          /^[a-z0-9_]{3,24}$/.test(username),
          'Use 3–24 letters, numbers or underscores for your username',
        );
        assert(
          !(await db.prepare('SELECT user_id FROM profiles WHERE username=?').get(username)),
          'That username is taken. Choose another.',
          409,
        );
        const guestId = id(),
          salt = randomBytes(16).toString('hex');
        const user = {
          id: guestId,
          name: inputText(body.name, 'Name', 60),
          email: `guest-${guestId}@guest.splitly.local`,
          salt,
          password: Buffer.from(await derive(randomBytes(32).toString('hex'), salt, 64)).toString(
            'hex',
          ),
        };
        await db
          .prepare('INSERT INTO users VALUES(?,?,?,?,?)')
          .run(user.id, user.email, user.name, user.salt, user.password);
        await db
          .prepare('INSERT INTO profiles(user_id,username,photo) VALUES(?,?,?)')
          .run(user.id, username, '');
        const token = randomBytes(32).toString('hex');
        await db
          .prepare('INSERT INTO sessions VALUES(?,?,?)')
          .run(hash(token), user.id, Date.now() + 3650 * 86400_000);
        return await send(200, { token, user: await publicUser(user) });
      }
      if (['register', 'login'].includes(segments[1]) && req.method === 'POST') {
        throttle(`auth:${req.socket.remoteAddress}`);
        const email = inputText(body.email, 'Email', 254).toLowerCase();
        assert(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email), 'Enter a valid email');
        const password = String(body.password || '');
        assert(
          password.length >= 8 && password.length <= 128,
          'Password must contain 8–128 characters',
        );
        let user;
        if (segments[1] === 'register') {
          assert(
            !(await db.prepare('SELECT id FROM users WHERE email=?').get(email)),
            'An account already exists for this email',
            409,
          );
          const salt = randomBytes(16).toString('hex');
          user = {
            id: id(),
            email,
            name: inputText(body.name, 'Name', 60),
            salt,
            password: Buffer.from(await derive(password, salt, 64)).toString('hex'),
          };
          try {
            await db
              .prepare('INSERT INTO users VALUES(?,?,?,?,?)')
              .run(user.id, user.email, user.name, user.salt, user.password);
          } catch (e) {
            if (String(e.message).includes('UNIQUE'))
              assert(false, 'An account already exists for this email', 409);
            throw e;
          }
        } else {
          user = await db.prepare('SELECT * FROM users WHERE email=?').get(email);
          const actual = Buffer.from(await derive(password, user?.salt || 'memogo-dummy-salt', 64));
          assert(
            user && timingSafeEqual(actual, Buffer.from(user.password, 'hex')),
            'Email or password is incorrect',
            401,
          );
        }
        await db.prepare('DELETE FROM sessions WHERE expires < ?').run(Date.now());
        const token = randomBytes(32).toString('hex');
        await db
          .prepare('INSERT INTO sessions VALUES(?,?,?)')
          .run(hash(token), user.id, Date.now() + 30 * 86400_000);
        return await send(200, { token, user: await publicUser(user) });
      }
      const token = (req.headers.authorization || '').replace(/^Bearer /, '');
      const user = await db
        .prepare(
          'SELECT users.* FROM users JOIN sessions ON users.id=sessions.user_id WHERE sessions.token=? AND sessions.expires>?',
        )
        .get(hash(token), Date.now());
      assert(user, 'Please sign in again', 401);
      if (url.pathname === '/api/google/link' && req.method === 'POST') {
        throttle(`google-link:${user.id}`, 10);
        await googleAccount(await googleAuth.exchange(body.code,body.verifier),user);
        return await send(200, await publicUser(user));
      }
      if (
        body.clientRequestId &&
        !['logout'].includes(segments[1]) &&
        !(segments[3] === 'expenses' && req.method === 'POST')
      ) {
        assert(/^[a-zA-Z0-9_-]{16,100}$/.test(body.clientRequestId), 'Invalid offline request ID');
        const previous = await db
          .prepare('SELECT * FROM operations WHERE user_id=? AND request_id=?')
          .get(user.id, body.clientRequestId);
        if (previous) {
          assert(
            previous.path === `${req.method}:${url.pathname}` &&
              previous.signature === requestSignature(body),
            'This update already synced. Refresh before changing it.',
            409,
          );
          const recorded = JSON.parse(previous.response);
          if (recorded.members) {
            const latest = await db.prepare('SELECT data FROM trips WHERE id=?').get(recorded.id);
            if (!latest) return await send(200, {ok:true});
            const currentTrip=JSON.parse(latest.data);
            assert(currentTrip.members.some(member=>member.userId===user.id),'You do not have access to this group',403);
            return await send(200, await decorate(currentTrip,user));
          }
          return await send(200, recorded.profile ? await publicUser(user) : recorded);
        }
        operation = {
          userId: user.id,
          id: body.clientRequestId,
          path: `${req.method}:${url.pathname}`,
          signature: requestSignature(body),
        };
      }
      if (segments[1] === 'logout' && req.method === 'POST') {
        await db.prepare('DELETE FROM sessions WHERE token=?').run(hash(token));
        return await send(200, { ok: true });
      }
      if (segments[1] === 'me') {
        if (req.method === 'PATCH') {
          const current = await publicUser(user);
          const nextName = inputText(body.name ?? user.name, 'Name', 60);
          const username = String(body.username ?? current.username ?? '')
            .trim()
            .toLowerCase();
          {
            assert(/^[a-z0-9_]{3,24}$/.test(username), 'Use 3–24 letters, numbers or underscores');
            const taken = await db
              .prepare('SELECT user_id FROM profiles WHERE username=?')
              .get(username);
            assert(!taken || taken.user_id === user.id, 'That username is taken', 409);
          }
          const photo = body.photo ?? current.photo ?? '';
          assert(
            typeof photo === 'string' &&
              photo.length < 120000 &&
              (!photo || photo === current.photo || /^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(photo)),
            'Choose a smaller profile photo',
          );
          if (username)
            await db
              .prepare(
                'INSERT INTO profiles(user_id,username,photo) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET username=excluded.username,photo=excluded.photo',
              )
              .run(user.id, username, photo);
          user.name = nextName;
          await db.prepare('UPDATE users SET name=? WHERE id=?').run(user.name, user.id);
          for (const row of await db.prepare('SELECT data FROM trips').all()) {
            const group = JSON.parse(row.data);
            const person = group.members.find((m) => m.userId === user.id);
            if (person && person.name !== user.name) {
              snapshots.set(group, auditSnapshot(group));
              person.name = user.name;
              event(group, user, 'updated their name');
              await save(group);
            }
          }
        }
        return await send(200, await publicUser(user));
      }
      if (segments[1] === 'join' && req.method === 'POST') {
        throttle(`join:${user.id}`, 30);
        const row = await db.prepare('SELECT data FROM trips WHERE code=?').get(
          String(body.code || '')
            .trim()
            .toUpperCase(),
        );
        assert(row, 'Group code not found', 404);
        const trip = JSON.parse(row.data);
        snapshots.set(trip, auditSnapshot(trip));
        if (segments[2] === 'preview')
          return await send(200, {
            name: trip.name,
            joined: trip.members.some(member=>member.userId===user.id),
            guests: trip.members.filter((m) => !m.userId).map((m) => ({ id: m.id, name: m.name })),
          });
        if (!trip.members.some((m) => m.userId === user.id)) {
          if (body.memberId) {
            const guest = trip.members.find((m) => m.id === body.memberId);
            assert(
              guest && !guest.userId,
              'That guest was already claimed. Please check the group again.',
              409,
            );
            guest.userId = user.id;
            guest.name = user.name;
          } else {
            assert(trip.members.length < 100, 'This group is full');
            trip.members.push({ id: id(), name: user.name, userId: user.id });
          }
          event(trip, user, 'joined the group');
          await save(trip);
        }
        return await send(200, await decorate(trip, user));
      }
      assert(segments[1] === 'trips', 'Not found', 404);
      if (!segments[2]) {
        if (req.method === 'GET') {
          const trips = (await db.prepare('SELECT data FROM trips').all())
            .map((r) => JSON.parse(r.data))
            .filter((t) => t.members.some((m) => m.userId === user.id))
            .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
          return await send(200, await Promise.all(trips.map((t) => decorate(t, user))));
        }
        assert(req.method === 'POST', 'Method not allowed', 405);
        assert(Object.hasOwn(currencies, body.currency || 'INR'), 'Choose a supported currency');
        const tripId=clientId(body.id);
        assert(!(await db.prepare('SELECT id FROM trips WHERE id=?').get(tripId)), 'Group ID already exists',409);
        const trip = {
          id: tripId,
          code: randomBytes(6).toString('hex').toUpperCase(),
          ownerId: user.id,
          name: inputText(body.name, 'Group name', 80),
          currency: body.currency || 'INR',
          members: [{ id: clientId(body.me), name: user.name, userId: user.id }],
          expenses: [],
          transfers: [],
          activity: [],
          updatedAt: '',
        };
        if (body.guests !== undefined) {
          assert(
            Array.isArray(body.guests) && body.guests.length <= 30,
            'Add up to 30 guests at creation',
          );
          for (const [index, name] of body.guests.entries()) {
            const person=await resolvePerson(name);
            assert(!person.userId || !trip.members.some(member=>member.userId===person.userId),'This account is already included in the group',409);
            trip.members.push({
              id: clientId(body.memberIds?.[index]),
              ...person,
            });
          }
        }
        assert(new Set(trip.members.map(member=>member.id)).size===trip.members.length,'Member IDs must be unique');
        event(trip, user, 'created the group');
        await save(trip);
        return await send(201, await decorate(trip, user));
      }
      const row = await db.prepare('SELECT data FROM trips WHERE id=?').get(segments[2]);
      assert(row, 'Group not found', 404);
      const trip = JSON.parse(row.data);
      snapshots.set(trip, auditSnapshot(trip));
      assert(
        trip.members.some((m) => m.userId === user.id),
        'You do not have access to this group',
        403,
      );
      const owner = () =>
        assert(trip.ownerId === user.id, 'Only the group creator can do this', 403);
      const member = (memberId) => {
        const m = trip.members.find((m) => m.id === memberId);
        assert(m, 'Member not found', 404);
        return m;
      };
      if (segments[3] === 'ai') {
        throttle(`ai:${user.id}`, Number(process.env.AI_RATE_LIMIT_PER_10M || 60));
        if (segments[4] === 'scan-receipt' && req.method === 'POST') {
          const analysis = await analyzeReceipt({ file: body, trip });
          return await send(200, analysis);
        }
        if (segments[4] === 'check-anomalies' && req.method === 'POST') {
          const check = detectExpenseAnomalies({
            candidate: body.expense || body,
            trip,
            receiptAnalysis: body.receiptAnalysis || null,
          });
          return await send(200, check);
        }
        if (segments[4] === 'forecast' && req.method === 'GET') {
          const forecast = forecastGroupSpending({ trip, budgets: trip.budgets || {} });
          return await send(200, forecast);
        }
        if (segments[4] === 'budgets' && req.method === 'POST') {
          const cat = inputText(body.category, 'Category', 40);
          const limitMinor = body.limit === 0 ? 0 : minor(String(body.limit), trip.currency);
          trip.budgets ||= {};
          trip.budgets[cat] = limitMinor;
          event(trip, user, `set monthly budget for ${cat}`);
          await save(trip);
          return await send(200, forecastGroupSpending({ trip, budgets: trip.budgets }));
        }
        if (segments[4] === 'assistant' && req.method === 'POST') {
          const decoratedTrip = await decorate(trip, user);
          const result = await runConversationalAgent({
            message: body.message,
            history: body.history || [],
            trip: decoratedTrip,
            user,
          });
          return await send(200, result);
        }
        assert(false, 'Unknown AI endpoint', 404);
      }
      if (segments[3] === 'attachments') {
        if (req.method === 'POST') {
          const attachmentId = inputText(body.id, 'File ID', 100);
          assert(/^[a-zA-Z0-9_-]{16,100}$/.test(attachmentId), 'Invalid file ID');
          const mime = String(body.mime || '');
          assert(
            ['image/jpeg', 'image/png', 'image/webp', 'application/pdf'].includes(mime),
            'Choose a JPG, PNG, WebP or PDF',
          );
          assert(
            typeof body.data === 'string' && /^[A-Za-z0-9+/]*={0,2}$/.test(body.data),
            'Invalid file',
          );
          const bytes = Buffer.from(body.data, 'base64');
          assert(bytes.length > 0 && bytes.length <= 2_000_000, 'Each file must be under 2 MB');
          const valid =
            mime === 'application/pdf'
              ? bytes.subarray(0, 5).toString() === '%PDF-'
              : mime === 'image/jpeg'
                ? bytes[0] === 255 && bytes[1] === 216
                : mime === 'image/png'
                  ? bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))
                  : bytes.subarray(0, 4).toString() === 'RIFF' &&
                    bytes.subarray(8, 12).toString() === 'WEBP';
          assert(valid, 'The file content does not match its type');
          const filename = inputText(body.name, 'Filename', 120).replace(/[\\/\r\n]/g, '_');
          const existing = await db
            .prepare('SELECT * FROM attachments WHERE id=?')
            .get(attachmentId);
          if (existing)
            assert(
              existing.trip_id === trip.id &&
                existing.user_id === user.id &&
                existing.data === body.data,
              'File ID already used',
              409,
            );
          else
            await db
              .prepare('INSERT INTO attachments VALUES(?,?,?,?,?,?)')
              .run(attachmentId, trip.id, user.id, filename, mime, body.data);
          return await send(200, { id: attachmentId, name: filename, mime, size: bytes.length });
        }
        assert(req.method === 'GET', 'Method not allowed', 405);
        const file = await db
          .prepare('SELECT * FROM attachments WHERE id=? AND trip_id=?')
          .get(segments[4], trip.id);
        assert(file, 'File not found', 404);
        assert(
          file.user_id === user.id ||
            trip.expenses.some((e) => e.attachments?.some((a) => a.id === file.id)),
          'File not found',
          404,
        );
        res.writeHead(200, {
          'Content-Type': file.mime,
          'Content-Disposition': `attachment; filename*=UTF-8''${encodeURIComponent(file.name)}`,
          'Cache-Control': 'no-store',
          'X-Content-Type-Options': 'nosniff',
        });
        return res.end(Buffer.from(file.data, 'base64'));
      }
      if (segments[3] === 'export' && req.method === 'GET') {
        const format = segments[4];
        assert(['pdf', 'xlsx'].includes(format), 'Choose PDF or XLSX');
        const output = await exportTrip(await decorate(trip, user), format, {
          analytics: url.searchParams.get('analytics') === '1',
        });
        res.writeHead(200, {
          'Content-Type':
            format === 'pdf'
              ? 'application/pdf'
              : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'Content-Disposition': `attachment; filename="splitly-${trip.id}.${format}"`,
          'Cache-Control': 'no-store',
          'X-Content-Type-Options': 'nosniff',
        });
        return res.end(output);
      }
      if (!segments[3]) {
        if (req.method === 'GET') return await send(200, await decorate(trip, user));
        owner();
        if (req.method === 'DELETE') {
          await db.prepare('DELETE FROM trips WHERE id=?').run(trip.id);
          return await send(200, { ok: true });
        }
        assert(req.method === 'PATCH', 'Method not allowed', 405);
        if (body.name !== undefined) trip.name = inputText(body.name, 'Group name', 80);
        event(trip, user, 'updated group settings');
      } else if (segments[3] === 'categories') {
        assert(req.method === 'POST', 'Method not allowed', 405);
        const category = inputText(body.name, 'Category', 40);
        trip.categories ||= [];
        if (
          ![...categories, ...trip.categories].some(
            (c) => c.toLowerCase() === category.toLowerCase(),
          )
        ) {
          assert(trip.categories.length < 100, 'This group has reached 100 custom categories');
          trip.categories.push(category);
          event(trip, user, `added category: ${category}`);
        } else return await send(200, await decorate(trip, user));
      } else if (segments[3] === 'members') {
        owner();
        if (req.method === 'POST') {
          assert(trip.members.length < 100, 'Group member limit reached');
          const person=await resolvePerson(body.name,body.username,body.email);
          assert(
            !person.userId || !trip.members.some((m) => m.userId === person.userId),
            'This user is already a member',
            409,
          );
          assert(!trip.members.some(member=>member.id===body.id),'Member ID already exists',409);
          trip.members.push({
            id: clientId(body.id),
            ...person,
          });
          event(trip, user, 'added a member');
        } else {
          const m = member(segments[4]);
          if (req.method === 'DELETE') {
            assert(m.userId !== trip.ownerId, 'The group creator cannot be removed');
            assert(
              !trip.expenses.some((e) =>
                [...e.shares, ...e.payers].some((p) => p.memberId === m.id),
              ) && !trip.transfers.some((t) => t.from === m.id || t.to === m.id),
              'A member with transactions cannot be removed; this preserves the group ledger',
            );
            trip.members = trip.members.filter((x) => x.id !== m.id);
            event(trip, user, 'removed a member');
          } else {
            assert(req.method === 'PATCH', 'Method not allowed', 405);
            assert(!m.userId,'Connected members use their profile name. They can change it in Profile.',409);
            m.name = inputText(body.name, 'Name', 60);
            event(trip, user, 'renamed a member');
          }
        }
      } else if (segments[3] === 'expenses') {
        if (req.method === 'DELETE') {
          const e = trip.expenses.find((e) => e.id === segments[4]);
          assert(e, 'Expense not found', 404);
          assert(
            e.createdBy === user.id || trip.ownerId === user.id,
            'Only its author or group creator can delete this expense',
            403,
          );
          trip.expenses = trip.expenses.filter((x) => x.id !== e.id);
          event(trip, user, `deleted expense: ${e.title}`);
        } else {
          assert(['POST', 'PATCH'].includes(req.method), 'Method not allowed', 405);
          if (req.method === 'POST' && body.clientRequestId !== undefined) {
            assert(
              typeof body.clientRequestId === 'string' &&
                /^[a-zA-Z0-9_-]{16,100}$/.test(body.clientRequestId),
              'Invalid offline request ID',
            );
            const operation = trip.operationIds?.[`${user.id}:${body.clientRequestId}`];
            if (operation) {
              assert(
                typeof operation === 'string' || operation.signature === requestSignature(body),
                'This bill already synced. Refresh the group, then edit the saved bill.',
                409,
              );
              return await send(200, await decorate(trip, user));
            }
          }
          const existing = segments[4] ? trip.expenses.find((e) => e.id === segments[4]) : null;
          assert(req.method !== 'PATCH' || existing, 'Expense not found', 404);
          assert(
            !existing || existing.createdBy === user.id || trip.ownerId === user.id,
            'Only its author or group creator can edit this expense',
            403,
          );
          assert(req.method !== 'POST' || !trip.expenses.some(entry=>entry.id===body.id),'Bill ID already exists',409);
          assert(trip.expenses.length < 3000 || existing, 'Group expense limit reached');
          assert(body.receipt === undefined, 'Use the attachment picker to add a file');
          const files = body.attachments ?? existing?.attachments ?? [];
          assert(Array.isArray(files) && files.length <= 3, 'Add up to 3 attachments');
          const attachments = await Promise.all(
            files.map(async (a) => {
              const file = await db
                .prepare('SELECT * FROM attachments WHERE id=? AND trip_id=?')
                .get(a.id, trip.id);
              assert(
                file &&
                  (file.user_id === user.id ||
                    existing?.attachments?.some((old) => old.id === file.id)),
                'Upload the attachment before saving',
              );
              return {
                id: file.id,
                name: file.name,
                mime: file.mime,
                size: Buffer.from(file.data, 'base64').length,
              };
            }),
          );
          const category = inputText(body.category || 'Other', 'Category', 40);
          trip.categories ||= [];
          if (![...categories, ...trip.categories].includes(category)) {
            assert(trip.categories.length < 100, 'Custom category limit reached');
            trip.categories.push(category);
          }
          const expense = {
            id: existing?.id || clientId(body.id),
            createdBy: existing?.createdBy || user.id,
            title: inputText(body.title, 'Expense title'),
            date: date(body.date),
            category,
            attachments,
            createdAt: existing?.createdAt || new Date().toISOString(),
            note: String(body.note || '')
              .trim()
              .slice(0, 2000),
            ...(existing?.receipt ? { receipt: existing.receipt } : {}),
            ...expenseFromInput(body, trip),
          };
          if (existing) trip.expenses[trip.expenses.indexOf(existing)] = expense;
          else trip.expenses.push(expense);
          if (!existing && body.clientRequestId) {
            trip.operationIds ||= {};
            trip.operationIds[`${user.id}:${body.clientRequestId}`] = {
              id: expense.id,
              signature: requestSignature(body),
            };
          }
          event(trip, user, `${existing ? 'updated' : 'added'} expense: ${expense.title}`);
        }
      } else if (segments[3] === 'transfers') {
        if (req.method === 'DELETE') {
          const t = trip.transfers.find((t) => t.id === segments[4]);
          assert(t, 'Transfer not found', 404);
          assert(
            t.createdBy === user.id || trip.ownerId === user.id,
            'Only its author or group creator can delete this transfer',
            403,
          );
          trip.transfers = trip.transfers.filter((x) => x.id !== t.id);
          event(trip, user, 'deleted a transfer');
        } else {
          assert(['POST', 'PATCH'].includes(req.method), 'Method not allowed', 405);
          const existing = segments[4] ? trip.transfers.find((t) => t.id === segments[4]) : null;
          assert(req.method !== 'PATCH' || existing, 'Transfer not found', 404);
          assert(
            !existing || existing.createdBy === user.id || trip.ownerId === user.id,
            'Only its author or group creator can edit this transfer',
            403,
          );
          member(body.from);
          member(body.to);
          assert(body.from !== body.to, 'Choose two different members');
          assert(req.method !== 'POST' || !trip.transfers.some(entry=>entry.id===body.id),'Transfer ID already exists',409);
          assert(trip.transfers.length < 3000 || existing, 'Transfer limit reached');
          const transfer = {
            id: existing?.id || clientId(body.id),
            createdBy: existing?.createdBy || user.id,
            createdAt: existing?.createdAt || new Date().toISOString(),
            from: body.from,
            to: body.to,
            amount: minor(body.amount, trip.currency),
            date: date(body.date),
            note: String(body.note || '')
              .trim()
              .slice(0, 500),
          };
          if (existing) trip.transfers[trip.transfers.indexOf(existing)] = transfer;
          else trip.transfers.push(transfer);
          event(
            trip,
            user,
            `${existing ? 'updated' : 'recorded'} a transfer from ${member(body.from).name} to ${member(body.to).name}`,
          );
        }
      } else assert(false, 'Not found', 404);
      await save(trip);
      return await send(200, await decorate(trip, user));
    } catch (error) {
      if (!error.status) console.error('API error:', error.message);
      if (!res.headersSent)
        send(error.status || 500, {
          error: error.status ? error.message : 'Something went wrong. Please try again.',
        });
    }
  };
}

const sql = postgres(Deno.env.get('SUPABASE_DB_URL')!, {prepare:false,max:1, idle_timeout:20, connection:{search_path:'splitbill'}});
const edgeAttempts = new Map();
Deno.serve(async (request) => {
  const original = new URL(request.url);
  const path = original.pathname.replace(/^.*?\/splitbill-api/, '');
  if (!path.startsWith('/api/')) return Response.json({error:'Not found'},{status:404});
  const bytes = new Uint8Array(await request.arrayBuffer());
  if (bytes.length > 3000000) return Response.json({error:'Request is too large'},{status:413});
  for (let attempt=0;attempt<3;attempt++) {
    try {
      return await sql.begin(async transaction => {
        await transaction.unsafe("set local statement_timeout = '15s'");
        await transaction.unsafe("set local lock_timeout = '10s'");
        await transaction`select pg_advisory_xact_lock(6751200)`;
        await transaction.unsafe('set local role splitbill_api');
        const db = {prepare(statement) {
          let n=0; const query=statement.replace(/\?/g,()=>'$'+(++n));
          const run=(...params)=>transaction.unsafe(query,params);
          return {run,all:run,get:async (...params)=>(await run(...params))[0]};
        }};
        const headers = {};
        let status=200, ended=false, output;
        const res={headersSent:false,setHeader(k,v){headers[k]=v;},writeHead(code,values={}){status=code;Object.assign(headers,values);},end(value){ended=true;output=value;this.headersSent=true;}};
        const req={method:request.method,url:path+original.search,headers:Object.fromEntries(request.headers),socket:{remoteAddress:request.headers.get('x-forwarded-for') || 'edge'}, async *[Symbol.asyncIterator](){if(bytes.length) yield Buffer.from(bytes);}};
        await createHandler(db,edgeAttempts)(req,res);
        if (!ended) throw new Error('Incomplete response');
        return new Response(output ?? null,{status,headers});
      });
    } catch(error) {
      if (['40001','40P01'].includes(error.code) && attempt<2) continue;
      console.error('Database request failed',error.code || error.name);
      return Response.json({error:'Service unavailable. Your saved changes can retry.'},{status:503});
    }
  }
});
